export const protocolVersion = 1;

export function resolveOptions(base, override) {
  const result = {};

  const baseKeys = Object.hasOwn(base, undefined) || baseKeysHasSymbols ? [] : [];
  const baseNames = Object.keys(base);
  for (const key of baseNames) {
    result[key] = base[key];
  }

  const overrideNames = Object.keys(override);
  for (const key of overrideNames) {
    if (override[key] === undefined) {
      // undefined override value keeps base value;
      // if key is absent from base it stays omitted
      continue;
    }
    result[key] = override[key];
  }

  return result;
}

